package com.laptopshop.dto;
import jakarta.validation.constraints.*; import java.math.BigDecimal;
public class LaptopDTO { private Integer id; @NotBlank(message="SKU không được để trống") @Size(max=30) private String sku; @NotBlank(message="Tên laptop không được để trống") @Size(max=200) private String name;
 @NotNull(message="Vui lòng chọn danh mục") private Integer categoryId; @NotNull(message="Vui lòng chọn thương hiệu") private Integer brandId;
 @Size(max=150) private String cpu; @Positive(message="RAM phải lớn hơn 0") private Integer ramGb; @Positive(message="Dung lượng lưu trữ phải lớn hơn 0") private Integer storageGb; @Size(max=150) private String gpu; private BigDecimal screenSize; @Size(max=100) private String operatingSystem; @Size(max=50) private String color;
 @NotNull @DecimalMin(value="0.0") private BigDecimal purchasePrice=BigDecimal.ZERO; @NotNull @DecimalMin(value="0.0") private BigDecimal salePrice; @NotNull @Min(0) private Integer stockQuantity=0; @Size(max=500) private String imageUrl; private String description; private Boolean isActive=true;
 public Integer getId(){return id;} public void setId(Integer v){id=v;} public String getSku(){return sku;} public void setSku(String v){sku=v;} public String getName(){return name;} public void setName(String v){name=v;} public Integer getCategoryId(){return categoryId;} public void setCategoryId(Integer v){categoryId=v;} public Integer getBrandId(){return brandId;} public void setBrandId(Integer v){brandId=v;}
 public String getCpu(){return cpu;} public void setCpu(String v){cpu=v;} public Integer getRamGb(){return ramGb;} public void setRamGb(Integer v){ramGb=v;} public Integer getStorageGb(){return storageGb;} public void setStorageGb(Integer v){storageGb=v;} public String getGpu(){return gpu;} public void setGpu(String v){gpu=v;} public BigDecimal getScreenSize(){return screenSize;} public void setScreenSize(BigDecimal v){screenSize=v;} public String getOperatingSystem(){return operatingSystem;} public void setOperatingSystem(String v){operatingSystem=v;} public String getColor(){return color;} public void setColor(String v){color=v;}
 public BigDecimal getPurchasePrice(){return purchasePrice;} public void setPurchasePrice(BigDecimal v){purchasePrice=v;} public BigDecimal getSalePrice(){return salePrice;} public void setSalePrice(BigDecimal v){salePrice=v;} public Integer getStockQuantity(){return stockQuantity;} public void setStockQuantity(Integer v){stockQuantity=v;} public String getImageUrl(){return imageUrl;} public void setImageUrl(String v){imageUrl=v;} public String getDescription(){return description;} public void setDescription(String v){description=v;} public Boolean getIsActive(){return isActive;} public void setIsActive(Boolean v){isActive=v;}}
